// entityLookup performs a binary search for the named entity.
// Mirrors md4c entity.c entity_lookup().
func entityLookup(name string) (entity, bool) {
	i, j := 0, len(entityMap)
	for i < j {
		h := i + (j-i)/2
		if entityMap[h].name < name {
			i = h + 1
		} else if entityMap[h].name > name {
			j = h
		} else {
			return entityMap[h], true
		}
	}
	return entity{}, false
}
